<template>
	<view class="container">
		<u-loading-page
		:loading="true" 
		v-if="load"
		fontSize="28rpx" />
		<block v-else>
		<view class="top" :style="{'backgroundImage':`url(${baseUrl}/uni/jf-shop-bg.png)`}">
			<view class="top-info">
				<view class="tit">可提现余额(元)</view>
				<view class="money">{{balance}}</view>
				<view class="mingxi" @click="toNext('/pages/my/withdraw-list')">提现记录</view>
			</view>
		</view>
		<view class="info">
			<view class="info-type">
				<view class="title">提现方式</view>
				<view class="type-items">
					<view class="type-item" :class="{'act':form.tx_type==1}" @click="changeType(1)" v-if="false">
						<image :src="form.tx_type==1?'/static/my/tx-wx.png':'/static/my/tx-wx-hui.png'" mode="widthFix" class="tx-img" />
						<text>微信</text>
					</view>
					<view class="type-item" :class="{'act':form.tx_type==2}" @click="changeType(2)">
						<image :src="form.tx_type==2?'/static/my/tx-yhk.png':'/static/my/tx-yhk-hui.png'" mode="widthFix" class="tx-img" />
						<text>银行卡</text>
					</view>
					<view class="type-item" :class="{'act':form.tx_type==3}" @click="changeType(3)">
						<image :src="form.tx_type==3?'/static/my/tx-zfb.png':'/static/my/tx-zfb-hui.png'" mode="widthFix" class="tx-img" />
						<text>支付宝</text>
					</view>
				</view>
			</view>
			<view class="info-type" v-if="form.tx_type==2">
				<view class="title">银行卡提现</view>
				<view class="bank-container" @click="toNext(`/pages/my/user-bank`)">
					<text>{{bank_name}}</text>
					<u-icon name="arrow-right" color="#353535" size="16" />
				</view>
			</view>
			<view class="info-type" v-if="form.tx_type==3">
				<view class="title">支付宝提现</view>
				<view class="bank-container" @click="toNext(`/pages/my/user-bank`)">
					<text>{{zhifubao}}</text>
					<u-icon name="arrow-right" color="#353535" size="16" />
				</view>
			</view>
			<view class="info-type">
				<view class="title">提现金额</view>
				<view class="input-container">
					<text>¥</text>
					<u-input
					    placeholder="请输入提现金额"
						border="none"
						type="number"
						placeholderClass="placeholder28"
						v-model="form.money"
						fontSize="50rpx"
					    clearable />
				</view>
			</view>
			<view class="form">
				<view class="form-row" v-if="user_with_sms_enable==1">
					<text class="row-left">验证码</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入验证码"
							border="none"
							type="number"
							maxlength="6"
							placeholderClass="placeholder30"
							v-model="form.code"
						    clearable />
					</view>
					<button type="default" size="mini" class="code-btn" :disabled="codeDisabled" @click="getCode">{{tips}}</button>
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="submit"
					:disabled="submitDisabled || tx_config.cash_open==0">{{tx_config.cash_open==0?'提现暂未开放':'立即提现'}}</button>
			</view>
		</view>
		</block>
		<u-code ref="uCode1" startText="获取验证码" :seconds="sms_time_out" @change="codeChange" change-text="Xs"
										@start="codeDisabled = true" @end="codeDisabled = false"></u-code>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	var _this;
	export default {
		data() {
			return {
				form:{
					step:1,
					tx_type:2,
					money:'',
					code:'',
				},
				balance:'',
				mobile:'',
				user_with_sms_enable:0,
				sms_time_out:60,
				tx_config:{},
				bank_name:'',
				zhifubao:'',
				submitDisabled:false,
				tips:'获取验证码',
				codeDisabled:false,
			}
		},
		onLoad(e) {
			_this = this;
			_this.tijiao()
		},
		methods: {
			changeType(type){
				if (_this.form.tx_type == type) {
					return
				}
				_this.form.tx_type = type
			},
			submit(){
				_this.form.step = 2
				_this.tijiao()
			},
			//提交
			async tijiao(){
				if (_this.form.step == 2) {
					let codeRule = {
						name: 'code',
						rules: ['require', 'integer', 'min:6'],
						errorMsg: {
							require: '请输入验证码',
							integer: '验证码只能为数字',
							min: '验证码为6位'
						}
					}
					var rule = [
						{
							name: 'money',
							rules: ['require', 'number'],
							errorMsg: {
								require: '请输入提现金额',
								number: '提现金额只能为数字'
							}
						}
						];
						if (this.user_with_sms_enable == 1) {
							rule.push(codeRule);
						}
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/tixian',_this.form)
				if (data.code==200) {
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/my/withdraw-list`,true)
					})
				}else if(data.code == 50){
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/my/user-bank?from=1`,true)
					})
				}else if(data.code == -1){
					_this.mobile = data.result.mobile
					_this.balance = data.result.balance
					_this.user_with_sms_enable = data.result.user_with_sms_enable
					_this.sms_time_out = data.result.sms_time_out
					_this.tx_config = data.result.tx_config
					_this.bank_name = data.result.bank_name
					_this.zhifubao = data.result.zhifubao
					if (_this.load) {
						_this.load = false
					}
				}else{
					uni.$u.toast(data.msg)
				}
			},
			//获取验证码
			async getCode() {
				if (this.$refs.uCode1.canGetCode) {
					const params = {
						user_id: this.user_id,
						scene: 5
					}
					const data = await _this.$post('port/send_code',params)
					if (data.code == 200) {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast('发送成功');
						// 通知验证码组件内部开始倒计时
						this.$refs.uCode1.start();
					} else {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast(data.msg);
					}
				} else {
					uni.$u.toast('请倒计时结束后再发送');
				}
			},
			codeChange(text) {
				this.tips = text;
			}
		}
	}
</script>

